WITH filtered AS (SELECT id, store_id, product_id, quantity, last_restock, DATEDIFF(CURRENT_DATE(), last_restock) AS days_since_last_restock FROM inventory WHERE last_restock > TO_DATE('2023-02-27')), deduped AS (SELECT *, RANK() OVER (PARTITION BY store_id ORDER BY days_since_last_restock DESC NULLS LAST) AS latest_rank FROM filtered QUALIFY latest_rank = 1), enriched AS (SELECT e.*, b.brand, b.product_name FROM deduped e INNER JOIN products b ON e.product_id = b.id), with_dims AS (SELECT s.id, s.store_id, s.product_id, s.quantity, s.days_since_last_restock, s.latest_rank, b.city, b.opened_date FROM enriched s LEFT JOIN stores b ON s.store_id = b.id WHERE b.opened_date >= '2025-07-28'), daily AS (SELECT city, DATE_TRUNC('QUARTER', opened_date) AS quarter_start, CASE WHEN quantity >= 234 THEN 'HIGH' ELSE 'LOW' END AS quantity_tier, SORT_ARRAY(COLLECT_SET(city)) AS city_list, COUNT(*) FILTER (WHERE city = 'London') AS london_rows, COUNT_IF(city = 'London') AS london_events, GROUPING_ID() AS gid FROM with_dims GROUP BY GROUPING SETS ((city, DATE_TRUNC('QUARTER', opened_date), CASE WHEN quantity >= 234 THEN 'HIGH' ELSE 'LOW' END), (city, DATE_TRUNC('QUARTER', opened_date)), ())) SELECT city, quarter_start, city_list, gid FROM daily ORDER BY city DESC NULLS LAST
